Tool response:
Tool: get_reservation_by_confirmation
Description: Fetch reservation details for a specific confirmation number including guest information and campsite details.
Parameters:
    {
      "type": "object",
      "properties": {
        "confirmation_number": {
          "type": "string",
          "description": "Unique confirmation number for the reservation",
          "title": "Confirmation Number"
        }
      },
      "required": [
        "confirmation_number"
      ]
    }

Tool response:
Tool: apply_military_discount
Description: Apply a 10% military discount to a specified reservation if the guest qualifies. Updates the discount amount and reason on the reservation.
Parameters:
    {
      "type": "object",
      "properties": {
        "reservation_id": {
          "type": "integer",
          "description": "Internal identifier for the reservation",
          "title": "Reservation Id"
        }
      },
      "required": [
        "reservation_id"
      ]
    }
